package ma.ebank.ebank; import org.springframework.context.annotation.*; import org.springframework.boot.CommandLineRunner; import java.math.BigDecimal;
@Configuration public class Seed { @Bean CommandLineRunner seed(AccountRepository r){return args->{for(int i=1;i<=3;i++){BankAccount a=new BankAccount();a.id="ACC-00"+i;a.ribReference="DEMO-RIB-00"+i;a.customerId=(long)i;a.balance=new BigDecimal("10000.00");a.agency=i==1?"Casablanca Centre":i==2?"Rabat Agdal":"Marrakech Gueliz";a.type=i==2?BankAccount.AccountType.SAVINGS_ACCOUNT:BankAccount.AccountType.CURRENT_ACCOUNT;r.save(a);}};}}